import {SKILLS,skillRank,skillText} from './core.js';
import {blessingInfo,RELICS} from './pillars.js';
import {ASTRAL_RELICS} from './astral.js';
import {RELIQUARY_ART} from './approved-reliquary-assets.js';
import {approvedSkillGlyph} from './approved-talent-icons.js';
import {elementLayoutScale} from './ui-display.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const pretty=s=>s?String(s)[0]+String(s).slice(1).toLocaleLowerCase('pt-BR'):'';
// These newer passives explicitly reuse the approved base glyph of their mechanic.
export function preparationSkillGlyph(skill){return approvedSkillGlyph({'prism-shelter':'guard','breath-encore':'breath'}[skill.id]||skill.id);}
export function abyssPreparationView(profile,abyss={}){
 const skills=SKILLS.filter(k=>profile.equipped.includes(k.id)||(k.passive&&profile.unlocked.includes(k.id))).map(k=>({id:k.id,name:k.name,text:skillText(profile,k.id),rank:skillRank(profile,k.id),passive:!!k.passive,art:'data:image/svg+xml;charset=utf-8,'+encodeURIComponent(preparationSkillGlyph(k).replace('<svg ','<svg style="color:#edf4ff" ')),type:'skill'}));
 const relics=[...RELICS.filter(r=>profile.relics.includes(r.id)).map(r=>({...r,founder:true})),...ASTRAL_RELICS.filter(r=>profile.astral?.equipped?.includes(r.id)).map(r=>({...r,founder:false}))].map(r=>({...r,art:RELIQUARY_ART[r.id],type:'relic'}));
 return {blessing:blessingInfo(profile.pendingBlessing,profile.pendingBlessingLevel,profile.pendingBlessingRoll),skills:skills.map(k=>({...k,key:'skill:'+k.id})),relics:relics.map(r=>({...r,key:'relic:'+r.id})),bestMeters:abyss.bestMeters??profile.abyssBest??0,maxWave:abyss.maxWave??null,leaderboard:abyss.leaderboard?.label||'Sem registro'};
}
const markup="<section class=\"pp-window\" aria-label=\"Preparação da próxima descida\">\n  <header class=\"pp-head\"><img class=\"pp-emblem\" alt=\"\"><div><h2>Preparação</h2><span>Abismo · próxima descida · 0 m</span></div><button type=\"button\" class=\"pp-button pp-info cursor-interaction\" aria-label=\"Sobre a preparação\" aria-expanded=\"false\">i</button><button type=\"button\" class=\"pp-button pp-close cursor-interaction\" aria-label=\"Fechar\">×</button></header>\n  <div class=\"pp-about\" hidden>Salas contínuas: profundidade aumenta o perigo e o saque. A tentativa começa em 0 m; o recorde permanece. Esta tela consulta sua build. Trocas continuam na Árvore e no Relicário. Passivas não ocupam os cinco espaços de habilidades.<div class=\"pp-history\"></div></div>\n  <section class=\"pp-blessing\" aria-label=\"Bênção e risco\"></section>\n  <div class=\"pp-body\">\n   <section class=\"pp-loadout\"><h3>Equipadas <span class=\"pp-count\"></span></h3><div class=\"pp-skills\" aria-label=\"Habilidades equipadas\"></div><h3 class=\"pp-passive-title\">Passivas <span></span></h3><div class=\"pp-passives\" aria-label=\"Passivas sempre ativas\"></div></section>\n   <section class=\"pp-right\"><h3>Relíquias <span class=\"pp-relic-count\"></span></h3><div class=\"pp-relics\" aria-label=\"Relíquias da próxima descida\"></div><section class=\"pp-detail\" aria-label=\"Efeito selecionado\" aria-live=\"polite\"><div class=\"pp-detail-head\"><img alt=\"\"><div><h3></h3><span></span></div></div><p></p></section></section>\n  </div>\n  <footer class=\"pp-foot\"><span>Conferir efeitos</span><button type=\"button\" class=\"pp-button pp-primary pp-back cursor-interaction\">‹ Voltar ao Abismo</button></footer>\n </section>";
export function mountAbyssPreparation(parent,{profile,abyss,onBack,onClose,onSelect=()=>{},initialId,initialScroll=0,onScroll=()=>{},softMode=()=>false,focus=true}={}){
 const doc=parent.ownerDocument,win=doc.defaultView,host=doc.createElement('section');host.id='gv-prep-next';host.setAttribute('aria-label','Preparação da próxima descida');host.innerHTML=markup;parent.append(host);
 const q=s=>host.querySelector(s),media=win.matchMedia('(prefers-reduced-motion:reduce)'),model=abyssPreparationView(profile,abyss),items=[...model.skills,...model.relics];let selected=items.some(i=>i.key===initialId)?initialId:items.find(i=>i.id==='fury')?.key||items[0]?.key||null,disposed=false;
 q('.pp-emblem').src='assets/abyss-gate-r2/gate-nav-4x-v01.png';q('.pp-back').dataset.primary='true';q('.pp-body').tabIndex=0;
 function button(item,type){return '<button type="button" class="pp-item cursor-interaction" data-item="'+esc(item.key)+'" aria-pressed="'+(item.key===selected)+'" aria-label="Ver efeito de '+esc(item.name)+'"><img src="'+esc(item.art)+'" alt=""><span class="pp-name">'+esc(type==='relic'?pretty(item.name):item.name)+(type==='relic'?'<span class="pp-tier">'+(item.founder?'Fundadora':'Equipada')+'</span>':'')+'</span>'+(type==='skill'?'<span class="pp-level">Nv. '+item.rank+'</span>':'')+'</button>';}
 const equipped=model.skills.filter(k=>!k.passive),passives=model.skills.filter(k=>k.passive),founders=model.relics.filter(r=>r.founder).length;
 q('.pp-count').textContent=equipped.length+'/5';q('.pp-skills').innerHTML=equipped.map(k=>button(k,'skill')).join('')||'<p class="pp-empty">Nenhuma habilidade equipada.</p>';
 q('.pp-passive-title span').textContent=passives.length;q('.pp-passives').innerHTML=passives.map(k=>button(k,'passive')).join('')||'<p class="pp-empty">Nenhuma passiva aprendida.</p>';
 q('.pp-relic-count').textContent=(model.relics.length-founders)+' equipadas'+(founders?' · '+founders+' fundadora'+(founders>1?'s':''):'');q('.pp-relics').innerHTML=model.relics.map(r=>button(r,'relic')).join('')||'<p class="pp-empty">Nenhuma relíquia preparada.</p>';
 const b=model.blessing;q('.pp-blessing').innerHTML=b?'<div><small>Bênção'+(b.rarity?' · '+esc(pretty(b.rarity)):'')+'</small><div class="pp-blessing-name">'+esc(pretty(b.name))+'</div></div><div><small>Benefício</small><div class="pp-benefit">'+esc(b.good)+'</div></div><div><small>Risco'+(b.riskRank?' · '+esc(pretty(b.riskRank)):'')+'</small><div class="pp-risk">'+esc(b.risk)+'</div></div>':'<span class="pp-blessing-empty">Sem bênção preparada.</span>';
 q('.pp-history').textContent='Recorde '+model.bestMeters.toLocaleString('pt-BR')+' m · Maior onda: '+(model.maxWave??'Sem registro')+' · Classificação: '+model.leaderboard;
 function fit(){if(disposed)return;const scale=elementLayoutScale(host)||1,scene=win.getComputedStyle(parent),live=parent.parentElement.querySelector('#gvl-live'),available=(win.innerHeight-24)/scale-(parseFloat(scene.paddingTop)||0)-(parseFloat(scene.paddingBottom)||0)-(live?.offsetHeight||0);q('.pp-window').style.maxHeight=Math.max(180,Math.min(660,available))+'px';host.dataset.soft=String(softMode()||media.matches);}
 function detail(animate=false){const item=items.find(i=>i.key===selected);q('.pp-detail').hidden=!item;if(!item)return;q('.pp-detail img').src=item.art;q('.pp-detail h3').textContent=item.type==='relic'?pretty(item.name):item.name;q('.pp-detail-head span').textContent=item.type==='relic'?(item.founder?'Relíquia fundadora':'Relíquia equipada'):item.passive?'Passiva · sempre ativa':'Equipada · Nv. '+item.rank;q('.pp-detail p').textContent=item.text;host.querySelectorAll('[data-item]').forEach(e=>e.setAttribute('aria-pressed',String(e.dataset.item===selected)));q('.pp-detail').classList.remove('pp-confirm');if(animate&&host.dataset.soft!=='true'){void q('.pp-detail').offsetWidth;q('.pp-detail').classList.add('pp-confirm');}if(animate&&host.clientWidth<=440)q('.pp-detail').scrollIntoView({block:'nearest',behavior:host.dataset.soft==='true'?'instant':'smooth'});}
 function click(e){const button=e.target.closest('button');if(!button||button.disabled||disposed)return;if(button.dataset.item){selected=button.dataset.item;detail(true);onSelect(selected);}else if(button.matches('.pp-info')){const about=q('.pp-about');about.hidden=!about.hidden;button.setAttribute('aria-expanded',String(!about.hidden));}else if(button.matches('.pp-back'))onBack();else if(button.matches('.pp-close'))onClose();}
 function key(e){if(e.key!=='Tab')return;const stops=[q('.pp-info'),q('.pp-close'),q('.pp-body'),...host.querySelectorAll('[data-item]'),q('.pp-back')],active=host.getRootNode().activeElement,i=stops.indexOf(active);if(i<0||e.shiftKey&&i===0||!e.shiftKey&&i===stops.length-1){e.preventDefault();stops[e.shiftKey?stops.length-1:0].focus({preventScroll:true});}e.stopPropagation();}
 function scroll(){onScroll(q('.pp-body').scrollTop);}
 const resize=new win.ResizeObserver(fit);resize.observe(host);host.addEventListener('click',click);host.addEventListener('keydown',key);q('.pp-body').addEventListener('scroll',scroll);win.addEventListener('resize',fit);media.addEventListener('change',fit);fit();detail();q('.pp-body').scrollTop=initialScroll;if(focus)q('.pp-back').focus({preventScroll:true});
 return ()=>{if(disposed)return;scroll();disposed=true;resize.disconnect();host.removeEventListener('click',click);host.removeEventListener('keydown',key);q('.pp-body').removeEventListener('scroll',scroll);win.removeEventListener('resize',fit);media.removeEventListener('change',fit);host.remove();};
}
